"""One-off: backfill the new tag vocabulary onto historic runs, drop the junk.

Run with --apply to execute; without it, prints what it would do.

Backfill only ever derives tags from what a run already recorded. Where a
value genuinely was not captured at the time -- `dvc_exp` did not exist -- it
writes "unknown" rather than guessing "workspace", because a wrong value here
is worse than an absent one: it would silently claim a --temp variant run was
a workspace run.
"""

import sys

import mlflow

APPLY = "--apply" in sys.argv
EXPERIMENT = "4"
JUNK_EXPERIMENT = "2"  # test-proxy-check

JUNK_RUN_NAMES = {
    "chill-yak-899", "sincere-donkey-702", "brawny-asp-820",
    "nosy-goat-116", "efficient-mouse-655", "gifted-jay-388",
}

client = mlflow.MlflowClient()


def derive_tags(run) -> dict:
    name = run.data.tags.get("mlflow.runName", "")
    params, tags = run.data.params, run.data.tags

    # Both historic quantized naming eras: tflite-int8-* then *-quantized.
    stage = "quantized" if ("quantized" in name or name.startswith("tflite-int8")) else "train"

    head = params.get("head")
    if not head:
        head = "xgboost" if name.startswith("xgboost") else "cnn" if name.startswith("cnn") else None

    # git_branch == "HEAD" is the detached-worktree bug; the commit MLflow
    # recorded for free is the only thing that can stand in for it.
    branch = tags.get("git_branch")
    commit = tags.get("mlflow.source.git.commit", "")
    if branch and branch != "HEAD":
        git_ref = branch
    elif commit:
        git_ref = f"detached@{commit[:7]}"
    else:
        git_ref = "unknown"

    new = {"stage": stage, "git_ref": git_ref, "dvc_exp": "unknown", "backfilled": "true"}
    if head:
        new["head"] = head
    if params.get("feature_type"):
        new["feature_type"] = params["feature_type"]
    if params.get("balanced_data_md5"):
        new["dataset_md5"] = params["balanced_data_md5"]
    return {k: v for k, v in new.items() if tags.get(k) != v}


runs = mlflow.search_runs(experiment_ids=[EXPERIMENT], output_format="list", max_results=500)
delete, backfill = [], []
for r in runs:
    name = r.data.tags.get("mlflow.runName", "")
    if name in JUNK_RUN_NAMES or r.info.status == "RUNNING":
        delete.append(r)
    else:
        new = derive_tags(r)
        if new:
            backfill.append((r, new))

print(f"{'APPLYING' if APPLY else 'DRY RUN'}: {len(delete)} deletions, {len(backfill)} backfills\n")

for r in delete:
    print(f"  delete  {r.data.tags.get('mlflow.runName'):<28} {r.info.run_id}")
    if APPLY:
        client.delete_run(r.info.run_id)

print()
for r, new in backfill:
    print(f"  tag     {r.data.tags.get('mlflow.runName','')[:40]:<42} "
          f"{' '.join(f'{k}={v[:24]}' for k, v in sorted(new.items()) if k != 'backfilled')}")
    if APPLY:
        for k, v in new.items():
            client.set_tag(r.info.run_id, k, v)

junk_runs = mlflow.search_runs(experiment_ids=[JUNK_EXPERIMENT], output_format="list")
print(f"\n  delete experiment test-proxy-check ({len(junk_runs)} run(s))")
if APPLY:
    client.delete_experiment(JUNK_EXPERIMENT)

if not APPLY:
    print("\nRe-run with --apply to execute. MLflow deletes are soft: "
          "client.restore_run(<id>) / restore_experiment(<id>) reverses them.")

